import pandas as pd

def top_percentile_fraud(fraud: pd.DataFrame) -> pd.DataFrame:
    df = fraud.copy()
    def get_prank(group):
        n = len(group)
        if n == 1:
            group['p_rank'] = 0.0
        else:
            rank = group['fraud_score'].rank(ascending=False, method='min')
            group['p_rank'] = (rank - 1) / (n - 1)
        return group

    ranked = df.groupby('state', group_keys=False).apply(get_prank)
    filtered = ranked[ranked['p_rank'] <= 0.05]
    res = filtered[['policy_id', 'state', 'fraud_score']]
    return res.sort_values(by=['state', 'fraud_score', 'policy_id'], ascending=[True, False, True])
